//! Gated parity tests against fixtures produced by the official TRELLIS.2
//! Python code (`o_voxel.io.write_vxz`, `cumesh.remeshing`, and
//! `o_voxel.postprocess.to_glb`).
//!
//! Fixtures are committed under `crates/lux3d-core/tests/fixtures/` and were
//! generated by:
//!
//! - `scripts/generate_ovox_official_fixtures.py` (official `.vxz` writer,
//!   335 deterministic voxels, one file per compression codec, metadata.json).
//! - `scripts/generate_cumesh_remesh_goldens.py` (official CuMesh diamond
//!   remesher, cube/sphere at resolution 32/64, band 1, project_back 0).
//! - `scripts/generate_ovox_to_glb_fixture.py` (official `to_glb`, unit cube
//!   and an 8^3 attribute volume, 64x64 PBR textures).
//!
//! Every test skips with a message when its fixture directory is absent, so a
//! checkout without generated fixtures still passes.

use std::collections::BTreeMap;
use std::fs::File;
use std::path::{Path, PathBuf};

use flate2::read::GzDecoder;
use ndarray::{Array2, Dimension};
use ndarray_npy::ReadNpyExt;
use serde_json::Value;
use sha2::{Digest, Sha256};

use lux3d_core::export::ovox::vxz::{VxzInfo, read_vxz, read_vxz_info};

fn fixtures_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures")
}

fn read_json(path: &Path) -> Value {
    let bytes = std::fs::read(path)
        .unwrap_or_else(|error| panic!("failed to read fixture {}: {error}", path.display()));
    serde_json::from_slice(&bytes)
        .unwrap_or_else(|error| panic!("failed to parse fixture {}: {error}", path.display()))
}

fn sha256_hex(bytes: &[u8]) -> String {
    let mut hasher = Sha256::new();
    hasher.update(bytes);
    format!("{:x}", hasher.finalize())
}

/// Reinterpret a plain-old-data slice as bytes for hashing.
///
/// The fixture metadata hashes come from `numpy.ndarray.tobytes()`; the test
/// runs on little-endian x86, where the raw element bytes match.
fn as_bytes<T>(slice: &[T]) -> &[u8] {
    assert!(
        cfg!(target_endian = "little"),
        "fixture hashes assume little-endian"
    );
    // SAFETY: `T` is a plain numeric element (f32/i32) with no padding and
    // the returned slice has the same lifetime and byte length as `slice`.
    unsafe { std::slice::from_raw_parts(slice.as_ptr().cast::<u8>(), std::mem::size_of_val(slice)) }
}

fn coord_key(value: &Value) -> [i64; 3] {
    let coord = value.as_array().expect("coordinate row");
    [
        coord[0].as_i64().expect("x"),
        coord[1].as_i64().expect("y"),
        coord[2].as_i64().expect("z"),
    ]
}

/// Compare a decoded grid row-by-row against the metadata emitted by the
/// official writer, independent of chunk z-order sorting.
fn assert_matches_metadata(
    grid: &lux3d_core::export::ovox::VoxelGrid,
    metadata: &Value,
    fixture: &str,
) {
    let coords = metadata["coord"].as_array().expect("metadata.coord");
    let attrs = metadata["attrs"].as_object().expect("metadata.attrs");
    assert_eq!(grid.coords.len(), coords.len(), "{fixture}: voxel count");

    let mut expected = BTreeMap::new();
    for (row, coord) in coords.iter().enumerate() {
        let key = coord_key(coord);
        let mut values = BTreeMap::new();
        for (name, rows) in attrs {
            let row_values = rows.as_array().expect("attr rows")[row]
                .as_array()
                .expect("attr row")
                .iter()
                .map(|value| value.as_u64().expect("uint8 attribute") as u8)
                .collect::<Vec<_>>();
            values.insert(name.clone(), row_values);
        }
        expected.insert(key, values);
    }

    for (row, coord) in grid.coords.iter().enumerate() {
        let key = [coord[0] as i64, coord[1] as i64, coord[2] as i64];
        let want = expected
            .get(&key)
            .unwrap_or_else(|| panic!("{fixture}: unexpected coordinate {key:?}"));
        for (name, values) in want {
            let attr = grid
                .attr(name)
                .unwrap_or_else(|| panic!("{fixture}: missing attribute {name}"));
            assert_eq!(
                attr.row(row).expect("attribute row"),
                &values[..],
                "{fixture}: {name} at {key:?}"
            );
        }
    }
}

fn check_official_vxz_header(info: &VxzInfo, compression: &str, fixture: &str) {
    assert_eq!(info.num_voxel, 335, "{fixture}: num_voxel");
    assert_eq!(info.chunk_size, 8, "{fixture}: chunk_size");
    assert_eq!(info.filter, "none", "{fixture}: filter");
    assert_eq!(info.attr_interleave, "as_is", "{fixture}: attr_interleave");
    assert_eq!(info.compression, compression, "{fixture}: compression");
    let expected_level = match compression {
        "none" => 0,
        "deflate" => 9,
        "lzma" => 9,
        "zstd" => 22,
        other => panic!("unexpected compression {other}"),
    };
    assert_eq!(
        info.compression_level, expected_level,
        "{fixture}: official default compression level"
    );
    assert_eq!(
        info.attr,
        vec![
            ("base_color".to_string(), 3),
            ("metallic".to_string(), 1),
            ("roughness".to_string(), 1),
            ("alpha".to_string(), 1),
        ],
        "{fixture}: attribute schema"
    );
    // 7x7x7 minus 8 corners with chunk_size 8 exercises negative chunk
    // indices and more than one chunk.
    assert_eq!(info.chunks.len(), 8, "{fixture}: chunk count");
    assert_eq!(
        info.raw_size,
        (335 * 3 * 4 + 335 * 6) as u64,
        "{fixture}: raw_size"
    );
    assert!(info.compressed_size > 0, "{fixture}: compressed_size");
    assert!(info.compress_ratio > 0.0, "{fixture}: compress_ratio");
}

#[test]
fn vxz_reads_official_none_deflate_lzma_fixtures() {
    let dir = fixtures_root().join("ovox");
    let metadata_path = dir.join("metadata.json");
    if !metadata_path.exists() {
        eprintln!(
            "skipping official .vxz fixtures: {} is absent (run \
             scripts/generate_ovox_official_fixtures.py)",
            metadata_path.display()
        );
        return;
    }
    let metadata = read_json(&metadata_path);
    let files = metadata["files"].as_object().expect("metadata.files");

    for compression in ["none", "deflate", "lzma"] {
        let name = format!("official_{compression}_as_is.vxz");
        let path = dir.join(&name);
        let info = read_vxz_info(&path).expect("official header");
        check_official_vxz_header(&info, compression, &name);
        assert_eq!(
            files[&name]["sha256"].as_str().unwrap(),
            sha256_hex(&std::fs::read(&path).unwrap()),
            "{name}: fixture file hash"
        );

        let grid = read_vxz(&path).unwrap_or_else(|error| {
            panic!("{name}: Rust reader rejected an official-written file: {error}")
        });
        assert_matches_metadata(&grid, &metadata, &name);
    }
}

#[test]
fn vxz_reports_official_zstd_fixture_as_unsupported() {
    let dir = fixtures_root().join("ovox");
    let path = dir.join("official_zstd_as_is.vxz");
    if !path.exists() {
        eprintln!(
            "skipping official zstd .vxz fixture: {} is absent (run \
             scripts/generate_ovox_official_fixtures.py)",
            path.display()
        );
        return;
    }
    let info = read_vxz_info(&path).expect("official zstd header");
    check_official_vxz_header(&info, "zstd", "official_zstd_as_is.vxz");
    let error = read_vxz(&path).expect_err("this build has no zstd decoder");
    assert!(
        error.to_string().contains("zstd"),
        "unexpected zstd error: {error}"
    );
}

fn read_gzip_npy<A, D>(path: &Path) -> ndarray::Array<A, D>
where
    A: ndarray_npy::ReadableElement,
    D: Dimension,
    ndarray::Array<A, D>: ndarray_npy::ReadNpyExt,
{
    let file = File::open(path)
        .unwrap_or_else(|error| panic!("failed to open {}: {error}", path.display()));
    ndarray::Array::<A, D>::read_npy(GzDecoder::new(file))
        .unwrap_or_else(|error| panic!("failed to decode {}: {error}", path.display()))
}

#[test]
fn cumesh_remesh_goldens_are_intact() {
    let root = fixtures_root().join("remesh");
    if !root.exists() {
        eprintln!(
            "skipping CuMesh remesh goldens: {} is absent (run \
             scripts/generate_cumesh_remesh_goldens.py)",
            root.display()
        );
        return;
    }

    for shape in ["cube", "sphere"] {
        for resolution in [32usize, 64] {
            let dir = root.join(format!("{shape}_res{resolution}"));
            let params_path = dir.join("params.json");
            assert!(params_path.exists(), "missing {}", params_path.display());
            let params = read_json(&params_path);
            assert_eq!(params["shape"].as_str(), Some(shape));
            assert_eq!(params["resolution"].as_u64(), Some(resolution as u64));
            assert_eq!(params["band"].as_f64(), Some(1.0));
            assert_eq!(params["project_back"].as_f64(), Some(0.0));
            assert_eq!(params["storage"].as_str(), Some("gzip(npy)"));

            let vertices: Array2<f32> = read_gzip_npy(&dir.join("vertices.npy.gz"));
            let faces: Array2<i32> = read_gzip_npy(&dir.join("faces.npy.gz"));
            let input_vertices: Array2<f32> = read_gzip_npy(&dir.join("input_vertices.npy.gz"));
            let input_faces: Array2<i32> = read_gzip_npy(&dir.join("input_faces.npy.gz"));

            assert_eq!(vertices.ncols(), 3, "{shape} {resolution}: vertex width");
            assert_eq!(faces.ncols(), 3, "{shape} {resolution}: face width");
            assert_eq!(input_vertices.ncols(), 3);
            assert_eq!(input_faces.ncols(), 3);
            assert_eq!(
                vertices.nrows(),
                params["output_vertices"].as_u64().unwrap() as usize,
                "{shape} {resolution}: output vertex count"
            );
            assert_eq!(
                faces.nrows(),
                params["output_faces"].as_u64().unwrap() as usize,
                "{shape} {resolution}: output face count"
            );
            assert_eq!(
                input_vertices.nrows(),
                params["input_vertices"].as_u64().unwrap() as usize
            );
            assert_eq!(
                input_faces.nrows(),
                params["input_faces"].as_u64().unwrap() as usize
            );

            assert_eq!(
                sha256_hex(as_bytes(vertices.as_slice().expect("contiguous vertices"))),
                params["sha256"]["vertices"].as_str().unwrap(),
                "{shape} {resolution}: vertex bytes"
            );
            assert_eq!(
                sha256_hex(as_bytes(faces.as_slice().expect("contiguous faces"))),
                params["sha256"]["faces"].as_str().unwrap(),
                "{shape} {resolution}: face bytes"
            );
            assert!(
                vertices.iter().all(|value| value.is_finite()),
                "{shape} {resolution}: non-finite vertex"
            );
            let vertex_count = vertices.nrows() as i32;
            assert!(
                faces
                    .iter()
                    .all(|&index| index >= 0 && index < vertex_count),
                "{shape} {resolution}: face index out of range"
            );

            // Recompute the postprocess.py AABB semantics from the stored
            // input mesh and compare with the recorded parameters.
            let mut min = [f32::INFINITY; 3];
            let mut max = [f32::NEG_INFINITY; 3];
            for row in input_vertices.rows() {
                for axis in 0..3 {
                    min[axis] = min[axis].min(row[axis]);
                    max[axis] = max[axis].max(row[axis]);
                }
            }
            let max_extent = (max[0] - min[0]).max(max[1] - min[1]).max(max[2] - min[2]) as f64;
            let expected_scale = (resolution as f64 + 3.0) / resolution as f64 * max_extent;
            let scale = params["scale"].as_f64().unwrap();
            assert!(
                (scale - expected_scale).abs() < 1e-6,
                "{shape} {resolution}: scale {scale} != {expected_scale}"
            );
            let center = params["center"].as_array().unwrap();
            for axis in 0..3 {
                let expected = (min[axis] as f64 + max[axis] as f64) / 2.0;
                assert!(
                    (center[axis].as_f64().unwrap() - expected).abs() < 1e-6,
                    "{shape} {resolution}: center axis {axis}"
                );
            }
        }
    }
}

/// Split a GLB container into its JSON document and the binary chunk.
fn parse_glb(bytes: &[u8]) -> (Value, &[u8]) {
    assert!(bytes.len() >= 12, "GLB is shorter than its 12-byte header");
    assert_eq!(&bytes[0..4], b"glTF", "GLB magic");
    assert_eq!(u32::from_le_bytes(bytes[4..8].try_into().unwrap()), 2);
    assert_eq!(
        u32::from_le_bytes(bytes[8..12].try_into().unwrap()) as usize,
        bytes.len(),
        "GLB declared length"
    );
    let mut offset = 12usize;
    let mut json = None;
    let mut binary = None;
    while offset < bytes.len() {
        let chunk_len = u32::from_le_bytes(bytes[offset..offset + 4].try_into().unwrap()) as usize;
        let chunk_type = u32::from_le_bytes(bytes[offset + 4..offset + 8].try_into().unwrap());
        let start = offset + 8;
        let end = start + chunk_len;
        assert!(end <= bytes.len(), "GLB chunk runs past the file");
        match chunk_type {
            0x4E4F_534A => json = Some(serde_json::from_slice(&bytes[start..end]).unwrap()),
            0x004E_4942 => binary = Some(&bytes[start..end]),
            other => panic!("unexpected GLB chunk type {other:#x}"),
        }
        offset = end;
    }
    (
        json.expect("GLB JSON chunk"),
        binary.expect("GLB binary chunk"),
    )
}

#[test]
fn official_to_glb_fixture_has_official_material_assembly() {
    let dir = fixtures_root().join("ovox");
    let glb_path = dir.join("official_to_glb.glb");
    let params_path = dir.join("to_glb_params.json");
    if !glb_path.exists() || !params_path.exists() {
        eprintln!(
            "skipping official to_glb fixture: {} is absent (run \
             scripts/generate_ovox_to_glb_fixture.py)",
            glb_path.display()
        );
        return;
    }
    let bytes = std::fs::read(&glb_path).unwrap();
    let params = read_json(&params_path);
    assert_eq!(
        params["glb_sha256"].as_str().unwrap(),
        sha256_hex(&bytes),
        "official to_glb fixture hash"
    );
    assert_eq!(params["glb_bytes"].as_u64().unwrap() as usize, bytes.len());

    let (json, binary) = parse_glb(&bytes);
    let material = &json["materials"][0];
    let pbr = &material["pbrMetallicRoughness"];
    assert_eq!(pbr["baseColorTexture"]["index"].as_u64(), Some(0));
    assert_eq!(pbr["metallicRoughnessTexture"]["index"].as_u64(), Some(1));
    assert_eq!(
        pbr["baseColorFactor"],
        serde_json::json!([1.0, 1.0, 1.0, 1.0])
    );
    assert_eq!(pbr["metallicFactor"].as_f64(), Some(1.0));
    assert_eq!(pbr["roughnessFactor"].as_f64(), Some(1.0));
    assert_eq!(material["alphaMode"].as_str(), Some("OPAQUE"));
    assert_eq!(material["doubleSided"].as_bool(), Some(true));

    let images = json["images"].as_array().expect("images");
    assert_eq!(images.len(), 2, "base color + metallic/roughness images");
    for image in images {
        assert_eq!(image["mimeType"].as_str(), Some("image/png"));
        let view = image["bufferView"].as_u64().expect("image bufferView") as usize;
        let range = &json["bufferViews"][view];
        let offset = range["byteOffset"].as_u64().unwrap_or(0) as usize;
        let length = range["byteLength"].as_u64().expect("bufferView length") as usize;
        assert!(offset + length <= binary.len(), "PNG outside binary chunk");
        assert_eq!(&binary[offset..offset + 8], b"\x89PNG\r\n\x1a\n");
    }

    let primitive = &json["meshes"][0]["primitives"][0];
    for attribute in ["POSITION", "NORMAL", "TEXCOORD_0"] {
        assert!(
            primitive["attributes"].get(attribute).is_some(),
            "missing {attribute}"
        );
    }
    let accessors = json["accessors"].as_array().expect("accessors");
    let position = primitive["attributes"]["POSITION"].as_u64().unwrap() as usize;
    let indices = primitive["indices"].as_u64().unwrap() as usize;
    assert_eq!(
        accessors[position]["count"].as_u64().unwrap() as usize,
        params["output_vertices"].as_u64().unwrap() as usize
    );
    assert_eq!(
        accessors[indices]["count"].as_u64().unwrap() as usize,
        params["output_faces"].as_u64().unwrap() as usize * 3
    );
    assert_eq!(
        params["base_color_texture_size"],
        serde_json::json!([64, 64])
    );
    assert_eq!(
        params["metallic_roughness_texture_size"],
        serde_json::json!([64, 64])
    );
}
